exports.returns:
(| { kind: 'none' }
  | { kind: 'pending'; request: AssistantRequest; waitingFor: string[] }
  | { kind: 'accepted'; request: AssistantRequest }
  | { kind: 'refused'; request: AssistantRequest; by: string })

(| { kind: 'gone' }
  /** A blocked person: « Unblock user » (D186). */
  | { kind: 'blocked'; userId: string }
  /** A voice message being recorded. */
  | { kind: 'recorder' }
  | { kind: 'composer' }
  /** An upgraded room is read-only: the new one takes over. */
  | { kind: 'replaced'; replacedBy: string }
  /** The composer stays, disabled, its hint saying why. */
  | { kind: 'cannot-post' }) | null

params.ts_type:
{
  isInCall: boolean
  isDirect: boolean
  isVoice: boolean
  mayPost: boolean
}

exports.returns:
(| { kind: 'user'; userId: string }
  | {
      kind: 'room'
      roomId: string
      eventId: string | null
      /** The servers to join through, named by the link (`?via=`). */
      via: readonly string[]
    }) | null
